INSERT INTO "projects" ("id", "title", "slug", "summary", "description", "thumbnail", "cover_image", "industry", "client_name", "project_url", "start_date", "end_date", "status", "is_featured", "thumbnail_type", "thumbnail_url", "thumbnail_video_url", "thumbnail_autoplay", "videos", "gallery_images", "is_preview") VALUES
  ('20000000-0000-4000-8000-000000000001', 'ShopKart — Multi-Vendor E-commerce Platform', 'shopkart-ecommerce-platform', 'A headless multi-vendor marketplace for a Dhaka retail group: storefronts, inventory and bKash checkout in one fast Next.js app.', 'ShopKart replaced a slow monolithic store with a headless Next.js storefront on Shopify. Vendors manage their own catalogues, orders flow into one dashboard, and customers check out with bKash or cards. Search, filtering and the cart are all server-rendered, so the site stays fast on low-end phones and slow connections.', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1200&q=80&auto=format&fit=crop', 'ecommerce', 'ShopKart', 'https://shopkart.example.com', '2026-01-15', '2026-04-30', 'published', true, 'image', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1200&q=80&auto=format&fit=crop', NULL, false, '["https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4", "https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4"]'::jsonb, '["https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1522542550221-31fd19575a2d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true),
  ('20000000-0000-4000-8000-000000000002', 'ClinicFlow — Clinic Management & Appointment System', 'clinicflow-management-system', 'Booking, reminders and patient records for a 12-clinic group in Dhaka: no-shows down, front-desk queues gone.', 'ClinicFlow gives each clinic a booking page, an appointment calendar and automated SMS reminders. Doctors see their day at a glance, receptionists rebook in two clicks, and patients get reminders that cut missed appointments. The whole system runs on one Next.js app with a PostgreSQL backend.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', 'healthcare', 'ClinicFlow', 'https://clinicflow.example.com', '2026-02-01', '2026-05-15', 'published', true, 'video', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', 'https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', true, '[]'::jsonb, '["https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true)
ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint

INSERT INTO "case_studies" ("id", "project_id", "title", "slug", "challenge", "research", "strategy", "results", "metrics", "is_featured", "status", "thumbnail_type", "thumbnail_url", "thumbnail_video_url", "thumbnail_autoplay", "videos", "gallery_images", "is_preview") VALUES
  ('20000000-0000-4000-8000-000000000011', '20000000-0000-4000-8000-000000000001', 'Scaling ShopKart: Checkout Conversion Up 38% After a Headless Rebuild', 'shopkart-case-study', 'ShopKart ran on a monolithic store that took over six seconds to load on mobile. Cart abandonment was above 60 percent, vendors could not update their own catalogues, and every flash sale risked taking the site down.', 'We interviewed five vendors and ten repeat customers, mapped the checkout funnel in analytics, and load-tested the store at three times peak traffic. The data pointed at one bottleneck: the storefront rendered everything on the server per request, with no caching at all.', 'We rebuilt the storefront headless with Next.js and Shopify: static product pages with incremental regeneration, a cached cart API, and a three-step checkout with bKash. Vendors got a simple dashboard for catalogue and order management.', 'Checkout conversion rose 38 percent in the first month. Median page load dropped from 6.4 seconds to 1.2 seconds, cart abandonment fell to 24 percent, and the store survived a flash sale at three times normal traffic without slowing down.', '{"conversionUplift": "+38%", "pageLoad": "1.2s", "cartAbandonment": "24%", "peakTraffic": "3x"}'::jsonb, true, 'published', 'image', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', NULL, false, '[]'::jsonb, '["https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1522542550221-31fd19575a2d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true),
  ('20000000-0000-4000-8000-000000000012', '20000000-0000-4000-8000-000000000002', 'ClinicFlow: Cutting No-Shows by a Third with Smart Reminders', 'clinicflow-case-study', 'Twelve clinics shared one paper diary. Patients forgot appointments, receptionists spent mornings on the phone, and no-show rates sat near 30 percent: empty slots the clinics could not fill.', 'We shadowed receptionists for a week across three clinics and surveyed 200 patients. Most patients wanted a reminder the evening before, and receptionists wanted one screen that showed the whole day.', 'We built a booking page per clinic, a shared calendar, and automated SMS reminders sent the evening before each appointment. Rebooking takes two clicks, and the day view shows gaps that can be filled from a waitlist.', 'No-shows fell by a third within six weeks. Receptionists save roughly two hours a day on phone calls, and the waitlist now fills most freed slots the same day.', '{"noShowReduction": "-33%", "receptionistTimeSaved": "2h/day", "clinicsOnboarded": "12"}'::jsonb, false, 'published', 'image', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=1200&q=80&auto=format&fit=crop', NULL, false, '[]'::jsonb, '["https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true)
ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint

