INSERT INTO "posts" ("id", "title", "slug", "excerpt", "content", "cover_image", "is_featured", "status", "publish_at", "thumbnail_type", "thumbnail_url", "thumbnail_video_url", "thumbnail_autoplay", "videos", "gallery_images", "is_preview") VALUES
  ('20000000-0000-4000-8000-000000000041', 'Building Fast E-commerce Sites with Next.js', 'building-fast-ecommerce-sites-with-nextjs', 'Speed is a feature: how server components, image optimization and edge caching make a store feel instant on slow connections.', 'Speed is the first feature a customer notices, and the first one they punish. A store that loads in one second feels instant; the same store at four seconds feels broken.

## Server components do the heavy lifting

Next.js server components let the product page render on the server and ship almost no JavaScript for the parts that never change: the product grid, the filters, the footer. The interactive pieces — cart, search, checkout — hydrate on top. The result is a page that paints fast and stays interactive.

## Images and caching finish the job

Most of the weight on a store page is images. Automatic image optimization serves each image at the size the device needs, and edge caching means repeat visits barely touch the origin. Together with server components, that is usually enough to bring a slow store under two seconds.', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&q=80&auto=format&fit=crop', true, 'published', '2026-10-12 10:00:00', 'image', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&q=80&auto=format&fit=crop', NULL, false, '[]'::jsonb, '["https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1522542550221-31fd19575a2d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true),
  ('20000000-0000-4000-8000-000000000042', 'A Practical Guide to WooCommerce Security for Bangladeshi Stores', 'woocommerce-security-guide-bangladesh', 'Fraud orders, fake accounts and brute-force logins: the attacks every WooCommerce store faces, and the defenses that actually work.', 'Every WooCommerce store in Bangladesh faces the same attacks: cash-on-delivery fraud orders, fake accounts created by bots, and brute-force login attempts against wp-admin. The fixes are not exotic — they are basic hygiene, applied consistently.

## Block fraud before it ships

The cheapest fraud defense is a phone check: confirm the number before dispatching a cash-on-delivery order, and flag repeat offenders by phone, IP and device. A small blocklist stops most repeat fraud without touching genuine customers.

## Harden the login and the checkout

Limit login attempts, enforce strong passwords, and keep WordPress, WooCommerce and every plugin updated. Most breached stores we have seen were running a plugin version from two years ago. Updates are boring, and they are the whole game.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', false, 'published', '2026-10-26 10:00:00', 'image', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&q=80&auto=format&fit=crop', NULL, false, '[]'::jsonb, '["https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true),
  ('20000000-0000-4000-8000-000000000043', 'From Idea to Launch: How I Plan a New Product', 'from-idea-to-launch-product-planning', 'A product starts as a one-page brief, not a codebase. The planning steps I use before writing a single line of code.', 'Most products fail in planning, not in code. Before I write anything, I write a one-page brief: who the product is for, the one problem it solves, and what success looks like in ninety days. If the brief does not fit on one page, the idea is not ready.

## Plan the smallest launch

The first version should do one thing well for a small group of real users. Everything else goes on a list for later. A small launch teaches more in a week than a big launch teaches in a quarter, because real users tell you what matters.

## Ship, measure, decide

Launch with analytics from day one, watch what users actually do, and let that decide the next feature. Planning is not a document you finish once — it is a loop you run after every release.', 'https://images.unsplash.com/photo-1522542550221-31fd19575a2d?w=1200&q=80&auto=format&fit=crop', false, 'published', '2026-11-02 10:00:00', 'image', 'https://images.unsplash.com/photo-1522542550221-31fd19575a2d?w=1200&q=80&auto=format&fit=crop', NULL, false, '[]'::jsonb, '["https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=1200&q=80&auto=format&fit=crop", "https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=1200&q=80&auto=format&fit=crop"]'::jsonb, true)
ON CONFLICT ("slug") DO NOTHING;
